using System;
public class C
{
    public void SwitchBasedPatternMatching(object o)
    {
        switch (o)
        {
            case int n when n == 1:
                Console.WriteLine("1"); break;
            case string s:
                Console.WriteLine("s"); break;
            case int n when n == 2:
                Console.WriteLine("2"); break;
        }
    }
}
